import { parse } from 'node-html-parser';
import postcss from 'postcss';
import selectorParser from 'postcss-selector-parser';

/**
 * Strip pseudo-classes (:hover, :focus-visible, ...) and pseudo-elements
 * (::before, ...) from a selector so it can be matched against the static DOM.
 * Returns null when the selector cannot be parsed or strips to nothing.
 */
export function stripPseudo(selectorText) {
  let stripped = null;
  try {
    selectorParser((selectors) => {
      selectors.walkPseudos((pseudo) => pseudo.remove());
      const s = String(selectors).trim();
      if (s.length > 0) stripped = s;
    }).processSync(selectorText);
  } catch {
    return null;
  }
  return stripped;
}

/**
 * Filter the nodes of a container (root or at-rule body).
 * Returns an array of new nodes preserving order.
 */
function filterNodes(nodes, matches) {
  const kept = [];
  for (const node of nodes) {
    if (node.type === 'rule') {
      const survivors = node.selectors.filter((sel) => matches(sel));
      if (survivors.length > 0) {
        kept.push(node.clone({ selectors: survivors }));
      }
    } else if (node.type === 'atrule') {
      const name = node.name.toLowerCase();
      // Always keep these regardless of usage.
      if (name === 'keyframes' || name === 'font-face' || name === '-webkit-keyframes' || name === '-moz-keyframes') {
        kept.push(node.clone());
        continue;
      }
      // Nesting at-rules: recurse, drop when nothing survives inside.
      if (
        node.nodes &&
        ['media', 'supports', 'container', 'document', 'layer'].includes(name)
      ) {
        const inner = filterNodes(node.nodes, matches);
        if (inner.length > 0) {
          kept.push(node.clone({ nodes: inner }));
        }
        continue;
      }
      // Other at-rules (e.g. @import, @charset) pass through untouched.
      kept.push(node.clone());
    } else {
      kept.push(node.clone());
    }
  }
  return kept;
}

/**
 * Given HTML and a CSS string, return the subset of CSS containing only the
 * rules whose selectors match elements in the document. Pseudo-classes and
 * pseudo-elements are stripped before matching, but the original selector
 * text is preserved in the output. @keyframes and @font-face are always kept,
 * emptied @media blocks are removed, and source order is preserved.
 */
export default function extract(html, css) {
  const root = parse(html);

  // Cache match results per stripped selector; collect every element once.
  const cache = new Map();

  const matches = (selectorText) => {
    const stripped = stripPseudo(selectorText);
    if (!stripped) return false;
    if (!cache.has(stripped)) {
      let hit = false;
      try {
        hit = root.querySelectorAll(stripped).length > 0;
      } catch {
        hit = false; // unsupported/invalid selector: treat as unused
      }
      cache.set(stripped, hit);
    }
    return cache.get(stripped);
  };

  const ast = postcss.parse(css);
  const keptNodes = filterNodes(ast.nodes, matches);

  const out = postcss.root();
  for (const node of keptNodes) out.append(node);
  return out.toString().trim();
}

export { extract };

