import { describe, it, expect } from 'vitest';
import { execSync } from 'node:child_process';
import postcss from 'postcss';
import extract from '../src/extract.js';

const HTML = `<!DOCTYPE html>
<html>
<body>
  <div class="card featured">
    <h1 class="title">Hello</h1>
    <p>Some text</p>
    <a href="#" class="btn">Go</a>
  </div>
  <ul id="list">
    <li>one</li>
  </ul>
</body>
</html>`;

const CSS = `
.card .title {
  color: crimson;
}

.card p,
.nope-also {
  margin: 0;
}

.btn:hover,
.btn:focus-visible {
  color: royalblue;
}

.unused-class {
  color: pink;
}

li > span {
  display: none;
}

@media print {
  .card p {
    color: black;
  }
  .still-unused {
    color: teal;
  }
}

@media (max-width: 1px) {
  .unused-class {
    color: green;
  }
  #nothing-here {
    top: 0;
  }
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@font-face {
  font-family: 'Fake Font';
  src: url('/fake.woff2') format('woff2');
}
`;

// Parse the extractor output into a list of [selectorList, body] pairs at the
// top level, so tests can assert exact surviving selector lists.
function topLevelRules(css) {
  const ast = postcss.parse(css);
  return ast.nodes.map((node) => {
    if (node.type === 'rule') return { type: 'rule', selectors: node.selectors };
    if (node.type === 'atrule') {
      return {
        type: 'atrule',
        name: node.name,
        params: node.params,
        selectors:
          node.name.toLowerCase() === 'keyframes'
            ? node.nodes.map((f) => f.selector)
            : undefined,
      };
    }
    return { type: node.type };
  });
}

describe('critical css extraction', () => {
  const out = extract(HTML, CSS);

  it('keeps exactly the used rules, in source order', () => {
    expect(topLevelRules(out)).toEqual([
      { type: 'rule', selectors: ['.card .title'] },
      // comma list is pruned to only the matching selector
      { type: 'rule', selectors: ['.card p'] },
      // survives because its stripped form (.btn) matches, original text kept
      { type: 'rule', selectors: ['.btn:hover', '.btn:focus-visible'] },
      // used-inside-media rule survives; unused sibling inside same media dropped
      {
        type: 'atrule',
        name: 'media',
        params: 'print',
        selectors: undefined,
      },
      // @keyframes always kept
      { type: 'atrule', name: 'keyframes', params: 'spin', selectors: ['from', 'to'] },
      // @font-face always kept
      { type: 'atrule', name: 'font-face', params: '', selectors: undefined },
    ]);
  });

  it('hover-only selector survives via its stripped form with original text intact', () => {
    expect(out).toContain('.btn:hover');
    expect(out).toContain('.btn:focus-visible');
  });

  it('drops the fully-unused media query entirely', () => {
    expect(out).not.toContain('max-width');
    expect(topLevelRules(out).filter((n) => n.type === 'atrule' && n.params.includes('max-width'))).toHaveLength(0);
  });

  it('keeps the used-inside-media rule within its media block', () => {
    const print = topLevelRules(out).find((n) => n.type === 'atrule' && n.params === 'print');
    const inner = postcss.parse('@media print{}').nodes[0];
    // re-parse from output
    const mediaNode = postcss.parse(out).nodes.find(
      (n) => n.type === 'atrule' && n.params === 'print'
    );
    expect(mediaNode).toBeDefined();
    void inner;
    void print;
    expect(mediaNode.nodes.map((n) => n.selector)).toEqual(['.card p']);
  });

  it('never emits unused selectors or rules', () => {
    for (const gone of ['.unused-class', '.nope-also', '.still-unused', '#nothing-here', 'li > span']) {
      expect(out).not.toContain(gone);
    }
  });
});

